/** Internal reference numbers: MOV-000001, EBK-000001, AUD-000001. Generated by the system, never typed. */
export type IdPrefix = "MOV" | "EBK" | "AUD";

const num = (cid?: string) => Number(cid?.split("-")[1]) || 0;
export const formatContentId = (prefix: IdPrefix, n: number) => `${prefix}-${String(n).padStart(6, "0")}`;

/**
 * The next number never used before: above every existing item, every draft that reserved one, and the
 * saved counter (which only goes up, so deleting the newest title does not free its number).
 */
export function nextContentId(prefix: IdPrefix, taken: (string | undefined)[], counter = 0): string {
  const max = taken.reduce<number>((m, c) => (c?.startsWith(prefix) ? Math.max(m, num(c)) : m), counter);
  return formatContentId(prefix, max + 1);
}

export const contentNumber = num;

/** Gives older items (created before IDs existed) a number, oldest first. New items sit at the front of the list. */
export function backfillIds<T extends { cid?: string }>(list: T[], prefix: IdPrefix): T[] {
  let n = list.reduce((m, i) => Math.max(m, num(i.cid)), 0);
  const out = [...list];
  for (let i = out.length - 1; i >= 0; i--) {
    if (!out[i]!.cid) out[i] = { ...out[i]!, cid: formatContentId(prefix, ++n) };
  }
  return out;
}
